  {
    "location": "Top left of the image",
    "fact": "The title reads 'Incidence of Condition A in US States'."
  },
  {
    "location": "Right side of the map",
    "fact": "The legend is labeled 'High' at the top and 'Low' at the bottom, with numerical ticks at 100, 80, 60, 40, 20, and 0."
