    "fact": "The state labeled 'WV' is West Virginia."
  },
  {
    "location": "Within the state polygons",
    "fact": "The state labeled 'AL' is Alabama."
  }
]
,
"public_definitions": [
  "The goal is to open the state detail record for the state with the highest incidence to route it into the priority follow-up workflow.",
  "The state incidence map is the evidence source for this decision.",
  "The options are to open the detail for West Virginia (WV), Utah (UT), or Alabama (AL)."
]
,
